"""Generate a sequence of values on the GPU and count them into a histogram.

Usage: python main.py <config-file>

The config file holds one line: "<count> <seed> <bins>".
"""

import struct
import sys

import wgpu

WORKGROUP_SIZE = 256

SHADER = """
struct Params {
    count: i32,
    seed: i32,
    bins: i32,
    pad: i32,
}

@group(0) @binding(0) var<uniform> p: Params;
@group(0) @binding(1) var<storage, read_write> hist: array<atomic<u32>>;

@compute @workgroup_size(%WORKGROUP_SIZE%)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = i32(gid.x);
    if (i >= p.count) {
        return;
    }

    // Every intermediate fits in a signed 32-bit integer.
    let a = ((i % 40000) * 1597 + p.seed + 51749) % 40000;
    let b = (a * a + a * 37 + 11) % 40009;
    let c = (b * 613 + 7919) % 40009;
    let d = (c + (i / 40000) * 7919) % 40009;
    let value = d % 1000;

    let bin = value * p.bins / 1000;
    atomicAdd(&hist[u32(bin)], 1u);
}
""".replace("%WORKGROUP_SIZE%", str(WORKGROUP_SIZE))


def read_config(path):
    with open(path, encoding="ascii") as f:
        count, seed, bins = (int(x) for x in f.read().split())
    return count, seed, bins


def histogram(count, seed, bins):
    device = wgpu.gpu.request_adapter_sync(
        power_preference="high-performance"
    ).request_device_sync()

    hist_size = bins * 4
    params = device.create_buffer_with_data(
        data=struct.pack("<iiii", count, seed, bins, 0),
        usage=wgpu.BufferUsage.UNIFORM,
    )
    hist = device.create_buffer_with_data(
        data=bytes(hist_size),
        usage=wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC,
    )

    module = device.create_shader_module(code=SHADER)
    pipeline = device.create_compute_pipeline(
        layout="auto",
        compute={"module": module, "entry_point": "main"},
    )
    bind_group = device.create_bind_group(
        layout=pipeline.get_bind_group_layout(0),
        entries=[
            {"binding": 0, "resource": {"buffer": params, "offset": 0, "size": params.size}},
            {"binding": 1, "resource": {"buffer": hist, "offset": 0, "size": hist.size}},
        ],
    )

    encoder = device.create_command_encoder()
    if count > 0:
        groups = (count + WORKGROUP_SIZE - 1) // WORKGROUP_SIZE
        compute = encoder.begin_compute_pass()
        compute.set_pipeline(pipeline)
        compute.set_bind_group(0, bind_group)
        compute.dispatch_workgroups(groups)
        compute.end()
    device.queue.submit([encoder.finish()])

    data = device.queue.read_buffer(hist)
    return list(struct.unpack(f"<{bins}I", bytes(data[:hist_size])))


def main(argv):
    count, seed, bins = read_config(argv[1])
    counts = histogram(count, seed, bins)

    lines = [f"BIN {index} {n}" for index, n in enumerate(counts)]
    lines.append(f"TOTAL {count}")
    sys.stdout.write("\n".join(lines) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

